create table public.project_change_requests(
id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id)on delete restrict,title text not null,description text not null,reason text not null,category text not null,requester_name text not null,requested_date date not null,
scope_impact text,schedule_impact text,budget_impact text,resource_impact text,quality_impact text,risk_impact text,recommendation text,status text not null default'Draft',implementation_owner_membership_id uuid references public.project_members(id)on delete restrict,implementation_target_date date,decision_notes text,withdrawal_notes text,implementation_outcome_notes text,
created_by uuid not null references public.profiles(id)on delete restrict,created_at timestamptz not null default now(),last_edited_by uuid not null references public.profiles(id)on delete restrict,last_edited_at timestamptz not null default now(),submitted_by uuid references public.profiles(id)on delete restrict,submitted_at timestamptz,decided_by uuid references public.profiles(id)on delete restrict,decided_at timestamptz,withdrawn_by uuid references public.profiles(id)on delete restrict,withdrawn_at timestamptz,implementation_plan_updated_by uuid references public.profiles(id)on delete restrict,implementation_plan_updated_at timestamptz,implementation_started_by uuid references public.profiles(id)on delete restrict,implementation_started_at timestamptz,outcome_recorded_by uuid references public.profiles(id)on delete restrict,outcome_recorded_at timestamptz,updated_at timestamptz not null default now(),
constraint change_category_check check(category in('Scope','Schedule','Budget','Resources','Quality','Technical','Risk','Other')),constraint change_status_check check(status in('Draft','Submitted','Approved','Rejected','Withdrawn','In Implementation','Implemented','Not Implemented')),constraint change_base_text_check check(char_length(btrim(title))between 1 and 200 and char_length(btrim(requester_name))between 1 and 200 and char_length(btrim(description))between 1 and 4000 and char_length(btrim(reason))between 1 and 4000),constraint change_requested_date_check check(requested_date<=current_date),
constraint change_optional_text_check check((scope_impact is null or char_length(btrim(scope_impact))between 1 and 4000)and(schedule_impact is null or char_length(btrim(schedule_impact))between 1 and 4000)and(budget_impact is null or char_length(btrim(budget_impact))between 1 and 4000)and(resource_impact is null or char_length(btrim(resource_impact))between 1 and 4000)and(quality_impact is null or char_length(btrim(quality_impact))between 1 and 4000)and(risk_impact is null or char_length(btrim(risk_impact))between 1 and 4000)and(recommendation is null or char_length(btrim(recommendation))between 1 and 4000)and(decision_notes is null or char_length(btrim(decision_notes))between 1 and 4000)and(withdrawal_notes is null or char_length(btrim(withdrawal_notes))between 1 and 4000)and(implementation_outcome_notes is null or char_length(btrim(implementation_outcome_notes))between 1 and 4000)),
constraint change_state_check check(
(status='Draft'and submitted_by is null and decided_by is null and withdrawn_by is null and implementation_owner_membership_id is null and outcome_recorded_by is null)
or(status='Submitted'and submitted_by is not null and submitted_at is not null and scope_impact is not null and schedule_impact is not null and budget_impact is not null and resource_impact is not null and quality_impact is not null and risk_impact is not null and recommendation is not null and decided_by is null and withdrawn_by is null and implementation_owner_membership_id is null and outcome_recorded_by is null)
or(status in('Approved','In Implementation','Implemented','Not Implemented')and submitted_by is not null and submitted_at is not null and decided_by is not null and decided_at is not null and decision_notes is not null and implementation_owner_membership_id is not null and implementation_target_date is not null and implementation_plan_updated_by is not null and implementation_plan_updated_at is not null and withdrawn_by is null and(status='Approved'and implementation_started_by is null and outcome_recorded_by is null or status='In Implementation'and implementation_started_by is not null and implementation_started_at is not null and outcome_recorded_by is null or status='Implemented'and implementation_started_by is not null and implementation_started_at is not null and outcome_recorded_by is not null and outcome_recorded_at is not null and implementation_outcome_notes is not null or status='Not Implemented'and outcome_recorded_by is not null and outcome_recorded_at is not null and implementation_outcome_notes is not null))
or(status='Rejected'and submitted_by is not null and decided_by is not null and decided_at is not null and decision_notes is not null and withdrawn_by is null and implementation_owner_membership_id is null and outcome_recorded_by is null)
or(status='Withdrawn'and withdrawn_by is not null and withdrawn_at is not null and withdrawal_notes is not null and decided_by is null and implementation_owner_membership_id is null and outcome_recorded_by is null)));
create index change_register_idx on public.project_change_requests(project_id,status,submitted_at desc,requested_date desc,id);create index change_target_idx on public.project_change_requests(project_id,implementation_target_date,id)where status in('Approved','In Implementation');
create function private.change_owner_eligible(p_project_id uuid,p_membership_id uuid)returns boolean language sql stable security definer set search_path=''as $$select exists(select 1 from public.project_members pm join public.projects p on p.id=pm.project_id join public.organization_members om on om.organization_id=p.organization_id and om.user_id=pm.user_id and om.status='Active'where pm.id=p_membership_id and pm.project_id=p_project_id and pm.left_at is null and(pm.access_level='Project Member'or(pm.access_level='Project Manager'and pm.user_id=p.project_manager_id)))$$;
create function private.protect_change()returns trigger language plpgsql security definer set search_path=''as $$begin if tg_op='INSERT'then if new.status<>'Draft'or new.created_by<>auth.uid()or new.last_edited_by<>auth.uid()then raise exception'Trusted Change Request values are invalid.'using errcode='23514';end if;return new;end if;if old.project_id<>new.project_id or old.created_by<>new.created_by or old.created_at<>new.created_at then raise exception'Change Request identity is immutable.'using errcode='42501';end if;if old.status in('Rejected','Withdrawn','Implemented','Not Implemented')then raise exception'Terminal Change Requests are immutable.'using errcode='42501';end if;if old.status<>'Draft'and(old.title<>new.title or old.description<>new.description or old.reason<>new.reason or old.category<>new.category or old.requester_name<>new.requester_name or old.requested_date<>new.requested_date or old.scope_impact is distinct from new.scope_impact or old.schedule_impact is distinct from new.schedule_impact or old.budget_impact is distinct from new.budget_impact or old.resource_impact is distinct from new.resource_impact or old.quality_impact is distinct from new.quality_impact or old.risk_impact is distinct from new.risk_impact or old.recommendation is distinct from new.recommendation)then raise exception'Submitted Change Request governance fields are immutable.'using errcode='42501';end if;if not((old.status='Draft'and new.status in('Draft','Submitted','Withdrawn'))or(old.status='Submitted'and new.status in('Submitted','Approved','Rejected','Withdrawn'))or(old.status='Approved'and new.status in('Approved','In Implementation','Not Implemented'))or(old.status='In Implementation'and new.status in('In Implementation','Implemented','Not Implemented')))then raise exception'Unsupported Change Request transition.'using errcode='22023';end if;new.updated_at:=now();return new;end $$;create trigger change_protect before insert or update on public.project_change_requests for each row execute function private.protect_change();
alter table public.project_change_requests enable row level security;create policy change_select on public.project_change_requests for select to authenticated using(private.can_manage_project(project_id)or(status<>'Draft'and private.has_project_access(project_id)));revoke all on public.project_change_requests from anon,authenticated;grant select on public.project_change_requests to authenticated;
create function public.create_project_change_request(p_project_id uuid,p_title text,p_description text,p_reason text,p_category text,p_requester_name text,p_requested_date date,p_scope text,p_schedule text,p_budget text,p_resource text,p_quality text,p_risk text,p_recommendation text)returns public.project_change_requests language plpgsql security definer set search_path=''as $$declare r public.project_change_requests%rowtype;begin if auth.uid()is null or not private.can_manage_project(p_project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;if p_requested_date>current_date then raise exception'Requested date cannot be in the future.'using errcode='22023';end if;insert into public.project_change_requests(project_id,title,description,reason,category,requester_name,requested_date,scope_impact,schedule_impact,budget_impact,resource_impact,quality_impact,risk_impact,recommendation,created_by,last_edited_by)values(p_project_id,btrim(p_title),btrim(p_description),btrim(p_reason),p_category,btrim(p_requester_name),p_requested_date,nullif(btrim(p_scope),''),nullif(btrim(p_schedule),''),nullif(btrim(p_budget),''),nullif(btrim(p_resource),''),nullif(btrim(p_quality),''),nullif(btrim(p_risk),''),nullif(btrim(p_recommendation),''),auth.uid(),auth.uid())returning*into r;return r;end $$;
create function public.update_project_change_request_draft(p_id uuid,p_title text,p_description text,p_reason text,p_category text,p_requester_name text,p_requested_date date,p_scope text,p_schedule text,p_budget text,p_resource text,p_quality text,p_risk text,p_recommendation text)returns public.project_change_requests language plpgsql security definer set search_path=''as $$declare x public.project_change_requests%rowtype;r public.project_change_requests%rowtype;begin select*into x from public.project_change_requests where id=p_id for update;if x.id is null or x.status<>'Draft'or not private.can_manage_project(x.project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;if p_requested_date>current_date then raise exception'Requested date cannot be in the future.'using errcode='22023';end if;update public.project_change_requests set title=btrim(p_title),description=btrim(p_description),reason=btrim(p_reason),category=p_category,requester_name=btrim(p_requester_name),requested_date=p_requested_date,scope_impact=nullif(btrim(p_scope),''),schedule_impact=nullif(btrim(p_schedule),''),budget_impact=nullif(btrim(p_budget),''),resource_impact=nullif(btrim(p_resource),''),quality_impact=nullif(btrim(p_quality),''),risk_impact=nullif(btrim(p_risk),''),recommendation=nullif(btrim(p_recommendation),''),last_edited_by=auth.uid(),last_edited_at=now()where id=p_id returning*into r;return r;end $$;
create function public.submit_project_change_request(p_id uuid,p_confirm boolean)returns public.project_change_requests language plpgsql security definer set search_path=''as $$declare x public.project_change_requests%rowtype;r public.project_change_requests%rowtype;begin select*into x from public.project_change_requests where id=p_id for update;if x.id is null or x.status<>'Draft'or not private.can_manage_project(x.project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;if p_confirm is not true then raise exception'Submission confirmation is required.'using errcode='22023';end if;if x.scope_impact is null or x.schedule_impact is null or x.budget_impact is null or x.resource_impact is null or x.quality_impact is null or x.risk_impact is null or x.recommendation is null then raise exception'Complete the impact assessment before submission.'using errcode='22023';end if;update public.project_change_requests set status='Submitted',submitted_by=auth.uid(),submitted_at=now()where id=p_id returning*into r;return r;end $$;
create function public.withdraw_project_change_request(p_id uuid,p_notes text,p_confirm boolean)returns public.project_change_requests language plpgsql security definer set search_path=''as $$declare x public.project_change_requests%rowtype;r public.project_change_requests%rowtype;begin select*into x from public.project_change_requests where id=p_id for update;if x.id is null or x.status not in('Draft','Submitted')or not private.can_manage_project(x.project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;if p_confirm is not true or nullif(btrim(p_notes),'')is null then raise exception'Withdrawal confirmation and notes are required.'using errcode='22023';end if;update public.project_change_requests set status='Withdrawn',withdrawal_notes=btrim(p_notes),withdrawn_by=auth.uid(),withdrawn_at=now()where id=p_id returning*into r;return r;end $$;
create function public.approve_project_change_request(p_id uuid,p_notes text,p_owner uuid,p_target date,p_confirm boolean)returns public.project_change_requests language plpgsql security definer set search_path=''as $$declare x public.project_change_requests%rowtype;r public.project_change_requests%rowtype;begin select*into x from public.project_change_requests where id=p_id for update;if x.id is null or x.status<>'Submitted'or not private.can_manage_project(x.project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;if p_confirm is not true or nullif(btrim(p_notes),'')is null then raise exception'Approval confirmation and notes are required.'using errcode='22023';end if;if p_target<current_date then raise exception'Implementation target date cannot precede approval.'using errcode='22023';end if;if not private.change_owner_eligible(x.project_id,p_owner)then raise exception'The implementation owner is not eligible.'using errcode='23514';end if;update public.project_change_requests set status='Approved',decision_notes=btrim(p_notes),decided_by=auth.uid(),decided_at=now(),implementation_owner_membership_id=p_owner,implementation_target_date=p_target,implementation_plan_updated_by=auth.uid(),implementation_plan_updated_at=now()where id=p_id returning*into r;return r;end $$;
create function public.reject_project_change_request(p_id uuid,p_notes text,p_confirm boolean)returns public.project_change_requests language plpgsql security definer set search_path=''as $$declare x public.project_change_requests%rowtype;r public.project_change_requests%rowtype;begin select*into x from public.project_change_requests where id=p_id for update;if x.id is null or x.status<>'Submitted'or not private.can_manage_project(x.project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;if p_confirm is not true or nullif(btrim(p_notes),'')is null then raise exception'Rejection confirmation and notes are required.'using errcode='22023';end if;update public.project_change_requests set status='Rejected',decision_notes=btrim(p_notes),decided_by=auth.uid(),decided_at=now()where id=p_id returning*into r;return r;end $$;
create function public.update_change_request_implementation_plan(p_id uuid,p_owner uuid,p_target date)returns public.project_change_requests language plpgsql security definer set search_path=''as $$declare x public.project_change_requests%rowtype;r public.project_change_requests%rowtype;begin select*into x from public.project_change_requests where id=p_id for update;if x.id is null or x.status not in('Approved','In Implementation')or not private.can_manage_project(x.project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;if p_target<x.decided_at::date then raise exception'Implementation target date cannot precede approval.'using errcode='22023';end if;if not private.change_owner_eligible(x.project_id,p_owner)then raise exception'The implementation owner is not eligible.'using errcode='23514';end if;update public.project_change_requests set implementation_owner_membership_id=p_owner,implementation_target_date=p_target,implementation_plan_updated_by=auth.uid(),implementation_plan_updated_at=now()where id=p_id returning*into r;return r;end $$;
create function public.start_change_request_implementation(p_id uuid,p_confirm boolean)returns public.project_change_requests language plpgsql security definer set search_path=''as $$declare x public.project_change_requests%rowtype;r public.project_change_requests%rowtype;begin select*into x from public.project_change_requests where id=p_id for update;if x.id is null or x.status<>'Approved'or not private.can_manage_project(x.project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;if p_confirm is not true then raise exception'Implementation start confirmation is required.'using errcode='22023';end if;update public.project_change_requests set status='In Implementation',implementation_started_by=auth.uid(),implementation_started_at=now()where id=p_id returning*into r;return r;end $$;
create function public.complete_project_change_request(p_id uuid,p_notes text,p_confirm boolean)returns public.project_change_requests language plpgsql security definer set search_path=''as $$declare x public.project_change_requests%rowtype;r public.project_change_requests%rowtype;begin select*into x from public.project_change_requests where id=p_id for update;if x.id is null or x.status<>'In Implementation'or not private.can_manage_project(x.project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;if p_confirm is not true or nullif(btrim(p_notes),'')is null then raise exception'Implementation confirmation and outcome notes are required.'using errcode='22023';end if;update public.project_change_requests set status='Implemented',implementation_outcome_notes=btrim(p_notes),outcome_recorded_by=auth.uid(),outcome_recorded_at=now()where id=p_id returning*into r;return r;end $$;
create function public.mark_project_change_request_not_implemented(p_id uuid,p_notes text,p_confirm boolean)returns public.project_change_requests language plpgsql security definer set search_path=''as $$declare x public.project_change_requests%rowtype;r public.project_change_requests%rowtype;begin select*into x from public.project_change_requests where id=p_id for update;if x.id is null or x.status not in('Approved','In Implementation')or not private.can_manage_project(x.project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;if p_confirm is not true or nullif(btrim(p_notes),'')is null then raise exception'Not Implemented confirmation and outcome notes are required.'using errcode='22023';end if;update public.project_change_requests set status='Not Implemented',implementation_outcome_notes=btrim(p_notes),outcome_recorded_by=auth.uid(),outcome_recorded_at=now()where id=p_id returning*into r;return r;end $$;
create function public.get_eligible_change_owners(p_project_id uuid)returns table(membership_id uuid,user_id uuid,full_name text,access_level text)language plpgsql stable security definer set search_path=''as $$begin if auth.uid()is null or not private.can_manage_project(p_project_id)then raise exception'Change Request operation is not permitted.'using errcode='42501';end if;return query select pm.id,pm.user_id,pr.full_name,pm.access_level from public.project_members pm join public.profiles pr on pr.id=pm.user_id join public.projects p on p.id=pm.project_id join public.organization_members om on om.organization_id=p.organization_id and om.user_id=pm.user_id and om.status='Active'where pm.project_id=p_project_id and pm.left_at is null and(pm.access_level='Project Member'or(pm.access_level='Project Manager'and pm.user_id=p.project_manager_id))order by pr.full_name,pm.id;end $$;
revoke all on function private.change_owner_eligible(uuid,uuid),private.protect_change()from public;revoke all on function public.create_project_change_request(uuid,text,text,text,text,text,date,text,text,text,text,text,text,text),public.update_project_change_request_draft(uuid,text,text,text,text,text,date,text,text,text,text,text,text,text),public.submit_project_change_request(uuid,boolean),public.withdraw_project_change_request(uuid,text,boolean),public.approve_project_change_request(uuid,text,uuid,date,boolean),public.reject_project_change_request(uuid,text,boolean),public.update_change_request_implementation_plan(uuid,uuid,date),public.start_change_request_implementation(uuid,boolean),public.complete_project_change_request(uuid,text,boolean),public.mark_project_change_request_not_implemented(uuid,text,boolean),public.get_eligible_change_owners(uuid)from public;grant execute on function public.create_project_change_request(uuid,text,text,text,text,text,date,text,text,text,text,text,text,text),public.update_project_change_request_draft(uuid,text,text,text,text,text,date,text,text,text,text,text,text,text),public.submit_project_change_request(uuid,boolean),public.withdraw_project_change_request(uuid,text,boolean),public.approve_project_change_request(uuid,text,uuid,date,boolean),public.reject_project_change_request(uuid,text,boolean),public.update_change_request_implementation_plan(uuid,uuid,date),public.start_change_request_implementation(uuid,boolean),public.complete_project_change_request(uuid,text,boolean),public.mark_project_change_request_not_implemented(uuid,text,boolean),public.get_eligible_change_owners(uuid)to authenticated;
